const Q = (() => {
  const before = [0];
  SURAHS.forEach((s, i) => before.push(before[i] + s[1]));
  const abs = (s, a) => before[s - 1] + a;
  const juzAbs = JUZ_STARTS.map(([s, a]) => abs(s, a));
  const juzOf = n => juzAbs.filter(x => x <= n).length;
  return {
    TOTAL: before[114],
    // عدد صفحات المصحف لمقطع (يُقرَّب لأقرب نصف صفحة، وأدناه نصف صفحة)
    pages(s, f, t, s2) { const a = abs(s, f), b = abs(s2 || s, t), x = Math.max(PG_E[b - 1] - PG_S[a - 1], 0) / 100; return Math.max(0.5, Math.round(x * 2) / 2); },
    abs, juzAbs,
    name: s => SURAHS[s - 1][0],
    count: s => SURAHS[s - 1][1],
    // الجزء (أو الأجزاء) التي تقع فيها الآيات
    juz(s, f, t, s2) {   // s2: سورة النهاية (افتراضياً نفس سورة البداية)
      const a = juzOf(abs(s, f)), b = juzOf(abs(s2 || s, t));
      return a === b ? [a] : Array.from({ length: b - a + 1 }, (_, i) => a + i);
    },
    juzText(s, f, t, s2) {
      const j = Q.juz(s, f, t, s2);
      return j.length === 1 ? `الجزء ${j[0]}` : `الأجزاء ${j[0]} – ${j[j.length - 1]}`;
    }
  };
})();

// القراء العشرة ورواتهم (القراءات العشر الصغرى: الشاطبية + الدرة) — العدّ الكوفي لمصحف المدينة للجميع
const QURRA = [
  ['nafi', 'نافع', [['qalun', 'قالون'], ['warsh', 'ورش']]],
  ['ibnkathir', 'ابن كثير', [['bazzi', 'البزي'], ['qunbul', 'قنبل']]],
  ['abuamr', 'أبو عمرو', [['duri_a', 'الدوري'], ['susi', 'السوسي']]],
  ['ibnamir', 'ابن عامر', [['hisham', 'هشام'], ['zakwan', 'ابن ذكوان']]],
  ['asim', 'عاصم', [['shuba', 'شعبة'], ['hafs', 'حفص'], ['hafs_qasr', 'حفص بقصر المنفصل']]],
  ['hamza', 'حمزة', [['khalaf_h', 'خلف'], ['khallad', 'خلاد']]],
  ['kisai', 'الكسائي', [['abulharith', 'أبو الحارث'], ['duri_k', 'الدوري']]],
  ['abujaafar', 'أبو جعفر', [['wardan', 'ابن وردان'], ['jammaz', 'ابن جماز']]],
  ['yaqub', 'يعقوب', [['ruways', 'رويس'], ['rawh', 'روح']]],
  ['khalaf10', 'خلف العاشر', [['ishaq', 'إسحاق'], ['idris', 'إدريس']]]
];
const RW = {};
QURRA.forEach(([, qn, rs]) => rs.forEach(([k, n]) => { RW[k] = { k, label: `${n} عن ${qn}`, short: `${n} (${qn})` }; }));

// الروايات العشرون الأصلية (بدون حفص بقصر المنفصل)، وتسمية البرامج
const ALL20 = [];
QURRA.forEach(([, , rs]) => rs.forEach(([k]) => { if (k !== 'hafs_qasr') ALL20.push(k); }));
const qariRawis = qk => ((QURRA.find(x => x[0] === qk) || [0, 0, []])[2]).filter(r => r[0] !== 'hafs_qasr').map(r => r[0]);
function enrLabel(kind, keys) {
  if (kind === 'riwaya') return RW[keys[0]].label;
  if (kind === 'qiraa') { const qr = QURRA.find(x => x[2].some(r => r[0] === keys[0])); return `قراءة ${qr[1].replace(/^أبو /, 'أبي ')} (${keys.map(k => RW[k].short.split(' (')[0]).join(' وَ ')})`; }
  if (ALL20.every(k => keys.includes(k))) return 'الجمع بين القراءات العشر';
  return 'جمع: ' + keys.map(k => RW[k].label).join(' + ');
}
